// Firewall verdict: first matching rule wins, default deny
const rules=[{action:"allow",proto:"tcp",lo:443,hi:443,src:"10.1."}];
function verdict(p){for(const r of rules){const pm=r.proto==='any'||r.proto===p.proto;const pt=p.port>=r.lo&&p.port<=r.hi;const sm=r.src==='any'||p.src.indexOf(r.src)===0;if(pm&&pt&&sm)return r.action;}return 'deny';}
const pkt={proto:"tcp",port:443,src:"10.1.2.3"};
console.log('verdict for '+JSON.stringify(pkt)+' => '+verdict(pkt));

